class StartDiagnosticCheckModal(modals.StartDiagnosticCheckModal):

    _MODAL_XPATH = '//div[@role="dialog"]'
    _EXECUTE = '//div[@role="dialog"]//button[*[contains(text(), "Start") or contains(text(), "OK")]]'


class CreateNewConfigurationModal(modals.CreateNewConfigurationModal):

    _MODAL_XPATH = '//div[@role="dialog"]'
    _COPY_PLAN_FROM_RADIO_XPATH = _MODAL_XPATH + '//p-radiobutton[@ng-reflect-label="Copy plan from:"]'
    _COPY_CONFIG_DROPDOWN_BUTTON_XPATH = _MODAL_XPATH + '//p-dropdown[@id="copyPlanDropdown"]'
    _COPY_CONFIG_OPTION_XPATH = _MODAL_XPATH + '//p-dropdownitem[.//div[text()="{}"]]'

    _CONFIGURATION_NAME_INPUT_XPATH = _MODAL_XPATH + '//input[@ng-reflect-name="planName"]'
    _CREATE_BUTTON_XPATH = _MODAL_XPATH + '//button[.//span[text()="OK"]]'

    def wait_for_creat_new_configuration_modal_appear(self, timeout):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def _copy_configuration(self, is_copy, copy_configuration_from, timeout):
        if not is_copy:
            return

        if copy_configuration_from:
            self.click_enabled_element((By.XPATH, self._COPY_PLAN_FROM_RADIO_XPATH), timeout)

            self.click_element_by_xpath(self._COPY_CONFIG_DROPDOWN_BUTTON_XPATH)

            copy_configuration_from_option = self._COPY_CONFIG_OPTION_XPATH.format(copy_configuration_from)

            self.wait_for_visibility((By.XPATH, copy_configuration_from_option))

            option_elem = self._driver.find_element_by_xpath(copy_configuration_from_option)
            self._driver.execute_script("arguments[0].click();", option_elem)
        else:
            raise AttributeError('param "copy_configuration_from" can not be None')

    def _configure_name(self, configuration_name, timeout):
        if configuration_name:
            self.insert_text_to_enable_element((By.XPATH, self._CONFIGURATION_NAME_INPUT_XPATH),
                                                configuration_name,
                                                timeout)

    def create_new_configuration(self, is_copy, copy_configuration_from, configuration_name, timeout=60):
        self._copy_configuration(is_copy, copy_configuration_from, timeout)
        self._configure_name(configuration_name, timeout)
        self.click_enabled_element((By.XPATH, self._CREATE_BUTTON_XPATH), timeout)


class AddObjectModal(modals.AddObjectModal):

    _MODAL_XPATH = '//div[@role="dialog"]'

    _OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH = '//div[@role="dialog"]//span[contains(text(), "Select object class")]'
    _OBJECT_CLASS_NAME_INPUT_XPATH = '//div[@role="dialog"]//span[contains(text(), "{}")]'

    _CHOOSE_OBJECT_CLASS_ITEM_XPATH = '//div[@role="dialog"]//ul[@role="listbox"]//li//span'

    _PLAN_FROM_ROW_DROPDOWN_BUTTON_XPATH = '//div[@role="dialog"]//p-dropdown[@formcontrolname="plan"]/div/span[1]'
    _PLAN_INPUT_XPATH = '//div[@role="dialog"]//p-dropdown[@formcontrolname="plan"]/div/span[contains(text(), "{}")]'

    _CHOOSE_PLAN_ITEM_ITEM_XPATH = '//div[@role="dialog"]//p-dropdown[@formcontrolname="plan"]//li//span'

    _COPY_FROM_BUTTON_XPATH = '//div[@role="dialog"]//p-dropdown[@formcontrolname="managedObject"]/div/span[1]'
    _SOURCE_MANAGED_OBJECT_INPUT_XPATH = ('//div[@role="dialog"]//p-dropdown[@formcontrolname="managedObject"]/'
                                          'div//span[contains(text(), "{}")]')

    _CHOOSE_COPY_ITEM_XPATH = '//div[@role="dialog"]//p-dropdown[@formcontrolname="managedObject"]//li//span'

    _INCLUDING_SUBOBJECT = '//div[@role="dialog"]//p-checkbox[@formcontrolname="copySubTree"]//label'

    _ID_INPUT_XPATH = '//div[@role="dialog"]//ot-input-number[@ng-reflect-name="objectId"]//input'
    _LOAD_DEFAULT_VALUE_XPATH = '//div[@role="dialog"]//div[@class="load-default-row"]//input'

    _SUBMIT_BUTTON_XPATH = '//div[@role="dialog"]//p-button[.//span[text()="Copy"]]'
    _CANCEL_BUTTON_XPATH = '//div[@role="dialog"]//p-button[.//span[text()="Cancel"]]'

    def wait_until_add_object_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def add_object(self, object_class_name, plan_to_copy_from=None, copy_from=None, include_subobject=False,
                   id_value=None, is_load_default_values=False, timeout=60):

        if self.element_exists((By.XPATH, self._OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH), 3):
            self.select_element_and_retry_if_select_failed(
                object_class_name, self._OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH,
                self._CHOOSE_OBJECT_CLASS_ITEM_XPATH, self._OBJECT_CLASS_NAME_INPUT_XPATH.format(object_class_name),
                timeout=timeout)

        if plan_to_copy_from and self.element_exists((By.XPATH, self._PLAN_FROM_ROW_DROPDOWN_BUTTON_XPATH), 1):
            self.select_element_and_retry_if_select_failed(
                plan_to_copy_from, self._PLAN_FROM_ROW_DROPDOWN_BUTTON_XPATH,
                self._CHOOSE_PLAN_ITEM_ITEM_XPATH, self._PLAN_INPUT_XPATH.format(plan_to_copy_from),
                timeout=timeout)

        if copy_from and self.element_exists((By.XPATH, self._COPY_FROM_BUTTON_XPATH), 1):
            self.select_element_and_retry_if_select_failed(
                copy_from, self._COPY_FROM_BUTTON_XPATH,
                self._CHOOSE_COPY_ITEM_XPATH,
                self._SOURCE_MANAGED_OBJECT_INPUT_XPATH.format(copy_from),
                timeout=timeout)

        if include_subobject and self.element_exists((By.XPATH, self._INCLUDING_SUBOBJECT), 1):
            self.click_enabled_element(self._INCLUDING_SUBOBJECT, timeout)

        if id_value:
            self.insert_text_to_enable_element((By.XPATH, self._ID_INPUT_XPATH), id_value, timeout)

    def submit(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._SUBMIT_BUTTON_XPATH), timeout)

    def select_element_and_retry_if_select_failed(self,
                                                  element_text,
                                                  button_xpath,
                                                  option_xpath,
                                                  check_element_xpath,
                                                  retry_times=3,
                                                  timeout=60):
        while retry_times > 0:
            self.select_element_from_dropdown_list_by_text_and_click(
                element_text,
                (By.XPATH, button_xpath),
                (By.XPATH, option_xpath),
                timeout
            )
            if self.element_exists((By.XPATH, check_element_xpath), 1):
               break
            time.sleep(1)
            retry_times -= 1

        time.sleep(1)
        if retry_times == 0:
            logging.info('failed to select element: {}'.format(element_text))


class AddNewObjectModal(modals.AddObjectModal):

    _MODAL_XPATH = '//div[@role="dialog"]'

    _OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH = '//div[@role="dialog"]//span[contains(text(), "Select object class")]'
    _CHOOSE_OBJECT_CLASS_ITEM_XPATH = '//div[@role="dialog"]//ul[@role="listbox"]//li//span'

    _ID_INPUT_XPATH = '//div[@role="dialog"]//ot-input-number[@ng-reflect-name="objectId"]//input'
    _SUBMIT_BUTTON_XPATH = '//div[@role="dialog"]//p-button[.//span[text()="Add"]]'
    _CANCEL_BUTTON_XPATH = '//div[@role="dialog"]//p-button[.//span[text()="Cancel"]]'

    def wait_until_add_object_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def add_object(self, object_name, object_id, timeout=60):

        if self.element_exists((By.XPATH, self._OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH), 3):
            self.select_element_from_dropdown_list_by_text_and_click(
                object_name,
                (By.XPATH, self._OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH),
                (By.XPATH, self._CHOOSE_OBJECT_CLASS_ITEM_XPATH),
                timeout
            )

        if object_id:
            self.insert_text_to_enable_element((By.XPATH, self._ID_INPUT_XPATH), object_id, timeout)

    def submit(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._SUBMIT_BUTTON_XPATH), timeout)


