class ActivatePlanModal(modals.ActivatePlanModal):
    """
    Class for activate plan modal, providing methods to manipulate elements on modal
    """
    _MODAL_XPATH = '//div[@role="dialog"]'
    _EXECUTE_BUTTON_XPATH = '//div[@role="dialog"]//p-button[@ng-reflect-label="Execute"]'
    _CONTINUE_BUTTON_XPATH = '//div[@role="dialog"]//p-button[@ng-reflect-label="Continue" and @ng-reflect-disabled="false"]'
    _CLOSE_BUTTON_XPATH = '//div[@role="dialog"]//p-button[@ng-reflect-label="Close"]'
    _DOWNLOAD_PLAN_LABEL_XPATH = '//label[contains(text(), "Download plan without activation")]'
    _DOWNLOAD_PLAN_CHECKBOX_XPATH = ('//label[contains(text(), "Download plan without activation")]'
                                     '/preceding-sibling::div//input')
    _ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH = ('//label[contains(text(), '
                                                             '"Activate plan despite of validation errors") '
                                                             'or contains(text(), '
                                                             '"Download plan despite of validation errors")]')
    _ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_INPUT_XPATH = ('//label[contains(text(), '
                                                             '"Activate plan despite of validation errors") '
                                                             'or contains(text(), '
                                                             '"Download plan despite of validation errors")]'
                                                             '/preceding-sibling::div//input')
    _FEEDBACK_TEXT_XPATH = '//div[@role="dialog"]//ot-instruction//span'

    _ERROR_TABLE_XPATH = "//blocks-activate-plan-progress-dialog//table"
    _ERROR_TABLE_TITLE_XPATH = "//blocks-activate-plan-progress-dialog//table//th"
    _ERROR_TABLE_CONTENT_XPATH = "//blocks-activate-plan-progress-dialog//table//td"

    def wait_until_actiavte_plan_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def close(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH))

    def _execute_under_granular_timeout(self, timeout):
        minimum_timeout = 2
        for _ in range(int(timeout / minimum_timeout)):
            if self.element_exists((By.XPATH, self._EXECUTE_BUTTON_XPATH), 1):
                self.click_enabled_element((By.XPATH, self._EXECUTE_BUTTON_XPATH), 1)

            if self.element_exists((By.XPATH, self._CONTINUE_BUTTON_XPATH), 1):
                try:
                    self.click_enabled_element((By.XPATH, self._CONTINUE_BUTTON_XPATH), 1)
                except TimeoutException:
                    logging.info("The continue button is already click or disappered")

            if self.element_exists(self._ERROR_TABLE_XPATH, 1):
                head_fields = self.get_text_from_all_matching_elements(
                    locator=(By.XPATH, self._ERROR_TABLE_TITLE_XPATH))
                content_fields = self.get_text_from_all_matching_elements(
                    locator=(By.XPATH, self._ERROR_TABLE_CONTENT_XPATH))

                head_field_num = len(head_fields)

                error_message = []
                for index in range(int(len(content_fields) / head_field_num)):
                    error_message.append(
                        dict(zip(head_fields, content_fields[index * len(head_fields): (index + 1) * head_field_num])))

                return error_message

            result = self.get_activation_result()
            if 'finished' in result:
                return result
            time.sleep(1)

        return "execute timeout"

    def execute(self, timeout=60):
        return self._execute_under_granular_timeout(timeout)

    def select_download_plan_without_activation(self, download_plan_without_activation=False):
        self.select_checkbox_by_specified_status(download_plan_without_activation,
                                                 self._DOWNLOAD_PLAN_CHECKBOX_XPATH,
                                                 self._DOWNLOAD_PLAN_LABEL_XPATH)

    def select_activate_or_download_plan_despite_errors(self, activate_plan_despite_errors=False, timeout=60):
        if self.element_exists((By.XPATH, self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate_plan_despite_errors,
                                                     self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_INPUT_XPATH,
                                                     self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH)

    def get_activation_result(self):
        try:
            elem = self.driver.find_element_by_xpath(self._FEEDBACK_TEXT_XPATH)
            return elem.text
        except:
            return ""


class LoadScfFileModal(modals.LoadScfFileModal):

    _MODAL_XPATH = '//div[@role="dialog"]'
    _CLOSE_BUTTON_XPATH = '//div[@role="dialog"]//p-button[@ng-reflect-label="Close"]'

    _LOAD_SCF_BUTTON_XPATH = '//div[@role="dialog"]//p-button[@ng-reflect-label="Load SCF"]'
    _CANCEL_BUTTON_XPATH = '//div[@role="dialog"]//p-button[@ng-reflect-label="Cancel"]'

    _LOAD_SCF_STATUS_XPATH = '//div[@role="dialog"]//span[@class="ot-text ng-star-inserted"]'

    def wait_until_load_file_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def load_scf(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._LOAD_SCF_BUTTON_XPATH), timeout)

    def close(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)

    def check_status_after_loading_scf_file(self, check_node=4, timeout=60):
        min_interval = 2
        for _ in range(int(timeout / min_interval)):
            status = self.get_load_scf_status()
            if "succeeded" in status:
                return True
            time.sleep(min_interval)
        return False

    def get_load_scf_status(self):
        try:
            elem = self.driver.find_element_by_xpath(self._LOAD_SCF_STATUS_XPATH)
            return elem.text
        except:
            return ""


